        ;@compiled_headers
        /*
         * Shared C extern declarations prepended to every [compiled] block by
         * nasm_to_jwasm.py before tiny_cc, so each block holds only its own function.
         * Symbols needing a caller-specific signature — divmod32 / divmod32_bin (a
         * 2-arg `(long,long)` vs a 3-arg `(long,int,int)` form) and lookup_cached_sector
         * (2nd arg a `long lba` in most callers but a `far *buf` in one) — or whose name
         * maps to different addresses / types across functions (LINE_BUF @0E28 vs @1464,
         * EOF_ANCHOR, DRIVER_VEC, IO_START, COUNT, CURSOR, and dos_fn_10's byte view of
         * DRIVER_TABLE) keep their per-function extern in the .c.  Everything else is
         * declared HERE, once.
         */
        /* ---- records (byte-packed, MSC /Zp1 — DOS 2.x-style kernel structures) ---- */
        /* System file table entry (SISNE's own layout).  NOTE: this is NOT the DOS 2.x
         * sf_entry, which is a 3-byte header (sf_ref_count/sf_mode/sf_attr, all DB) with
         * an embedded sys_fcb from offset 3 (verified in DOSSYM_v211.ASM).  SISNE's
         * record uses WORD ref-count/mode and its own field placement; the names below
         * are the DOS-concept equivalents, derived from SISNE's byte-exact usage. */
        struct system_file_table {
            unsigned int  s_refcnt;      /* 00: reference count (WORD; DOS uses a byte)*/
            union { unsigned int s_mode;       /* 02: open mode / handle             */
                    struct { unsigned char s_model;    /* 02: its low byte           */
                             unsigned char s_modeh; };};   /* 03: its high byte      */
            unsigned char s_attr;        /* 04: attribute                             */
            unsigned char s_flags;       /* 05: device info (drive in low nibble)     */
            unsigned char s_res;         /* 06:  ... high byte of the flags word       */
            struct drive_param_block far *s_devptr; /* 07: driver / DPB pointer       */
            unsigned int  s_firclu;      /* 0B: first cluster                         */
            unsigned int  s_time;        /* 0D: time                                  */
            unsigned int  s_date;        /* 0F: date                                  */
            union { long s_size;         /* 11: file size                             */
                    struct { unsigned int s_sizelo;    /* 11: its low word           */
                             unsigned int s_sizehi; };};   /* 13: its high word      */
            /* For a FILE record this is the 32-bit position; for a DRIVER record the
             * two halves are independent counters (SHIFT_DRIVER_RECORDS_FLAG ages the
             * low word, FIND_FREE_DRIVER_SLOT scans the high one).                  */
            union { long  s_offset;      /* 15: current byte position                 */
                    struct { unsigned int s_offlo;     /* 15: its low word           */
                             unsigned int s_offhi; };};   /* 17: its high word       */
            unsigned int  s_relclu;      /* 19: relative cluster index                */
            unsigned int  s_lastclu;     /* 1B: last cluster visited                  */
            /* Record tail.  For an OPEN FCB's SFT the fields below locate the file's
             * directory entry: DISPATCH_FCB_OPEN re-reads that sector and writes the
             * cached time/date/cluster/size back into it.  The sector number is split —
             * low word at 1Dh, high word at 2Fh.                                    */
            unsigned int  s_dirsec;      /* 1D: dir sector, low word                  */
            unsigned char s_direntx;     /* 1F: entry index in that sector            */
            unsigned char s_name[11];    /* 20: its 8.3 name                          */
            unsigned char s_pad2b[4];    /* 2B..2E                                    */
            unsigned int  s_dirsechi;    /* 2F: sector high word                      */
            unsigned int  s_ownpsp;      /* 31: owner segment (find_free stores SDA)  */
            unsigned char s_pad33[2];    /* 33..34                                    */
        };
        /* File-table block — DOS's chained SFT layout: a block header (next block
         * far ptr, offset 0FFFFh terminates the chain; record count) followed by
         * b_count 35h-byte records.  [402h] heads the chain; [418h] is a block too. */
        struct file_block {
            struct file_block far *b_next;     /* 00: next block in the chain      */
            union { unsigned int b_count;      /* 04: records in this block        */
                    struct { unsigned char b_countl;   /* 04: its low byte         */
                             unsigned char b_counth; };};  /* 05                   */
            struct system_file_table b_rec[1]; /* 06: the records (flexible)       */
        };
        /* Program segment prefix.  Only the job-file-table fields are described — they
         * are the only part SISNE reaches through SDA_PTR, which it points at the
         * current PSP (segment SDA_SRC_SEG, offset 0). */
        struct psp {
            unsigned char p_resv00[0x32];      /* 00: the PSP fields SISNE never reads */
            unsigned int  p_maxfiles;          /* 32: entries in the job file table     */
            union { unsigned char far *p_filetab;      /* 34: the table itself          */
                    struct { unsigned int p_filetaboff;    /* 34: its offset word       */
                             unsigned int p_filetabseg; };};  /* 36: its segment word   */
        };
        struct device_header {
            struct device_header far *dh_next; /* 00: next driver in chain         */
            unsigned int  dh_attr;             /* 04: device attribute word        */
            unsigned int  dh_strategy;         /* 06 */
            unsigned int  dh_interrupt;        /* 08 */
            char          dh_name[8];          /* 0A */
        };
        /* Drive parameter block — DOS 2.0 dpb (DOSSYM.ASM) through @18; SISNE reuses
         * @1C/@1E for free-space caching where DOS 2.0 keeps the current-dir text,
         * and appends the sector shift at @20.  These are the CHAIN dpbs headed at
         * [3FEh] (d_next links them) that the SFT records and
         * GET_DPB_BY_DRIVE_INDEX hand out — NOT the 51h-per-drive table at [414h],
         * which is the current-directory structure (struct cds_entry below).        */
        struct drive_param_block {
            unsigned char d_drive;             /* 00: drive number  (dpb_drive)    */
            unsigned char d_unit;              /* 01: unit within driver (dpb_UNIT)*/
            unsigned int  d_secsize;           /* 02: bytes per sector (sector_size)*/
            unsigned char d_clumax;            /* 04: sectors per cluster-1 (mask) */
            unsigned char d_clushift;          /* 05: cluster shift (cluster_shift)*/
            unsigned int  d_ressec;            /* 06: first FAT sector (first_FAT) */
            unsigned char d_fatcnt;            /* 08: number of FATs  (FAT_count)  */
            unsigned int  d_rootcnt;           /* 09: root dir entries (root_entries)*/
            unsigned int  d_firstdata;         /* 0B: first data sector (first_sector)*/
            unsigned int  d_maxclu;            /* 0D: highest cluster (max_cluster)*/
            unsigned char d_fatsize;           /* 0F: sectors per FAT (FAT_size)   */
            unsigned int  d_firstdir;          /* 10: first dir sector (dir_sector)*/
            struct device_header far *d_driver;/* 12: driver header  (driver_addr) */
            unsigned char d_media;             /* 16: media descriptor (dpb_media) */
            unsigned char d_rebuild;           /* 17: 0FFh=rebuild  (first_access) */
            unsigned char far *d_next;         /* 18: next DPB      (next_dpb)     */
            unsigned int  d_freeclu;           /* 1C: free-search start / FAT cache*/
            unsigned int  d_freecnt;           /* 1E: free count / FAT cache       */
            unsigned char d_secshift;          /* 20: log2 bytes/sector (byte->sector shift) */
        };
        /* Current-directory structure — DOS 3.x CDS, one 51h-byte entry per logical
         * drive in the table at [414h:416h] (SETUP_DRIVE_TABLE seeds each entry with
         * the "A:\" path text, flags 4000h, the drive's chain DPB, and the FFFFh
         * cluster trio).  Flags: bit 12 subst/assign remap, bit 13 volume id, bit 14
         * valid (cleared with the pointer).  c_pathoff is GET_CWD's limit ("len or
         * 2", seeded as the word 2).                                                */
        struct cds_entry {
            union { unsigned char c_path[0x43];        /* 00: current path ASCIIZ     */
                    struct { unsigned char c_drvletter;    /* 00: 'A' + drive         */
                             unsigned char c_pathrest[0x42]; };};  /* 01              */
            union { unsigned int c_flags;              /* 43: cds flags word          */
                    struct { unsigned char c_flagsl;       /* 43                      */
                             unsigned char c_flagsh; };};  /* 44                      */
            union { struct drive_param_block far *c_dpb;   /* 45: the drive's DPB     */
                    struct { unsigned int c_dpbo;          /* 45: its offset word     */
                             unsigned int c_dpbs; };};     /* 47: its segment word    */
            unsigned int  c_startclu;          /* 49: current-dir start cluster       */
            unsigned int  c_4b;                /* 4B: init 0FFFFh with 49h/4Dh        */
            unsigned int  c_4d;                /* 4D: init 0FFFFh (IFS/JOIN field)    */
            union { unsigned int c_pathoffw;   /* 4F: seeded as the word 2            */
                    struct { unsigned char c_pathoff;      /* 4F: root-path offset    */
                             unsigned char c_pad50; };};   /* 50                      */
        };
        struct dir_entry {                     /* 32-byte FAT directory entry       */
            char          de_name[11];         /* 00: 8.3 name + extension          */
            unsigned char de_attr;             /* 0B: attribute bits                */
            unsigned char de_res[10];          /* 0C: reserved                      */
            unsigned int  de_time;             /* 16 */
            unsigned int  de_date;             /* 18 */
            unsigned int  de_cluster;          /* 1A: first cluster                 */
            union { unsigned long de_size;     /* 1C: file size in bytes            */
                    struct { unsigned int de_sizelo;   /* 1C: its low word          */
                             unsigned int de_sizehi; };};  /* 1E: its high word     */
        };
        /* What INT 2Fh/4601 (the network EXEC hook) hands back for a program the
         * redirector owns: a directory entry with the reserved area squeezed out, so
         * time/date/cluster/size follow the attribute byte directly, then the two seed
         * values the loader needs.  Only EXEC_PROGRAM_FROM_PATH sees one. */
        struct exec_record {
            unsigned char x_name[11];          /* 00: 8.3 name                      */
            unsigned char x_attr;              /* 0B: attribute bits                */
            unsigned int  x_time;              /* 0C */
            unsigned int  x_date;              /* 0E */
            unsigned int  x_cluster;           /* 10: first cluster                 */
            unsigned long x_size;              /* 12: file size in bytes            */
            unsigned long x_seedsec;           /* 16: loader seed dir sector        */
            unsigned char x_seedattr;          /* 1A */
        };
        /* What an FCB find-first/find-next leaves in the DTA: the drive number, then
         * the 32-byte directory entry that matched.  The one-byte prefix is why the
         * entry sits at DTA+1 rather than at the DTA itself. */
        struct fcb_find {
            unsigned char d_drive;             /* 00: 1-based drive number          */
            struct dir_entry d_ent;            /* 01: the matched directory entry   */
        };
        /* SISNE file control block.  Matches DOS 2.x sys_fcb (DOSSYM_v211.ASM, verified
         * against microsoft/MS-DOS v2.0) through @18; f_size is FILSIZ+DRVBP as one
         * 32-bit value.  From @19 DOS has the cluster words FIRCLUS@19 / CLUSPOS@1B /
         * LSTCLUS@1D, but SISNE reads that area at BYTE granularity for device/driver
         * routing (the DOS device-mode reuse of the cluster fields) — so those keep
         * SISNE-functional names with the DOS structural offset noted.  The prefix is
         * also unioned: for an OPEN file fcb+6:fcb+0Eh holds the SFT far pointer (a
         * SISNE construct, NOT in the DOS source), so those accessors keep raw casts. */
        struct fcb {
            union { unsigned char f_prefix[12];    /* 00: drive/name/ext (SFT ptr @6 when open)*/
                    struct { unsigned char f_drvcode;  /* 00: caller drive designator */
                             unsigned char f_name[11]; };   /* 01: 8.3 name+ext   */
                    struct { unsigned int  f_drive_word;   /* 00: drive/handle word overlay */
                             unsigned int  f_handle;   /* 02: open handle          */
                             unsigned int  f_count;    /* 04: caller record count  */
                             unsigned int  f_sftoff;   /* 06: SFT record ptr (off) */
                             unsigned char f_pfx08[4]; };}; /* 08..0B              */
            unsigned int  f_extent;            /* 0C: current block (DOS fcb_EXTENT)  */
            union { unsigned int f_recsiz;     /* 0E: record size  (DOS fcb_RECSIZ)   */
                    unsigned int f_sftseg; };  /* 0E: SFT record ptr (seg) when open  */
            union { long f_size;               /* 10: file size    (DOS FILSIZ+DRVBP) */
                    struct { unsigned int f_sizelo;    /* 10: its low word         */
                             unsigned int f_sizehi; };};   /* 12: its high word    */
            unsigned int  f_date;              /* 14: date         (DOS fcb_FDATE)    */
            union { unsigned int  f_time;              /* 16: time         (DOS fcb_FTIME)    */
                    unsigned char f_timelo; };
            union { struct { unsigned char f_devid;    /* 18: device id (fcb_DEVID)   */
                             unsigned char f_drive; }; /* 19: drive/device (FIRCLUS lo)*/
                    unsigned int  f_devidw; }; /* 18: devid|drive word = net drv seg  */
            unsigned char f_flags;             /* 1A: status flags (DOS FIRCLUS hi)   */
            union { struct { unsigned int  f_cluspos;  /* 1B: cluster position(CLUSPOS)*/
                             unsigned char f_drvidx;   /* 1D: driver index (LSTCLUS lo)*/
                             unsigned int  f_netid; }; /* 1E: network id (LSTCLUS hi+pk)*/
                    /* A LOCAL open FCB caches its directory entry's position here, at
                     * the same offsets the SFT uses (s_dirsec/s_direntx): DOS_FN_10
                     * re-reads that sector to write the size/date/time back.  The high
                     * word of the sector number lives in f_devid.                    */
                    struct { unsigned char f_resv1b[2]; /* 1B                          */
                             unsigned int  f_dirsec;    /* 1D: dir sector, low word    */
                             unsigned char f_direntx; };/* 1F: entry index in sector   */
                    unsigned char far *f_devptr; }; /* 1B: driver vector (open FCB)    */
            unsigned char f_curec;             /* 20: current record (DOS fcb_NR)     */
            long          f_datetime;          /* 21: packed date/time; DOS fcb_RR    */
        };                                     /*     (random record) reused as d/t   */
        /* The FCB an AH=17h rename is handed: an ordinary FCB prefix, then the NEW 8.3
         * name at 11h — where a plain FCB keeps its size/date/time.  Declared
         * separately rather than as another arm of struct fcb because the replacement
         * name spans four of that struct's members. */
        struct fcb_rename {
            unsigned char r_drvcode;           /* 00: drive designator             */
            unsigned char r_name[11];          /* 01: the existing 8.3 name        */
            unsigned char r_resv0c[5];         /* 0C: extent/record-size area      */
            unsigned char r_newname[11];       /* 11: the replacement 8.3 name     */
        };
        /* The buffer an INT 21h AH=0Ah hands the line editor: a two-byte header (the
         * caller's limit, then how much has been typed) in front of the CR-terminated
         * text.  Not an FCB despite the address it lives at being named for one. */
        struct input_buf {
            unsigned char i_max;               /* 00: caller's buffer limit        */
            unsigned char i_len;               /* 01: characters currently typed   */
            unsigned char i_text[1];           /* 02: the line, CR-terminated      */
        };
        /* DOS extended FCB: a 7-byte prefix (FFh flag, 5 reserved bytes, an attribute
         * byte) in front of a normal FCB.  Callers hand these to the FCB handlers, which
         * skip the prefix via GET_EXTENDED_FCB_ATTR to reach the embedded FCB. */
        struct fcb_ext {
            unsigned char x_flag;              /* 00: FFh marks an extended FCB */
            unsigned char x_resv[5];           /* 01: reserved                  */
            unsigned char x_attr;              /* 06: attribute byte            */
            struct fcb    x_fcb;               /* 07: the normal FCB            */
        };
        /* DOS directory-search record (SDA @ 1434h): the parsed 8.3 search pattern (an
         * FCB name area) plus the directory-scan working state that overlays what a
         * plain FCB would use for its extent/size/date/cluster bytes. */
        struct dir_search {
            unsigned char f_drvcode;           /* 00: search drive designator          */
            unsigned char f_name[11];          /* 01: parsed 8.3 search pattern         */
            unsigned char s_attr;              /* 0C: search attribute mask             */
            unsigned int  s_cluster;           /* 0D: current directory cluster scanned */
            unsigned int  s_parent;            /* 0F: parent directory cluster          */
            struct drive_param_block far *s_dpb; /* 11: request DPB pointer             */
            unsigned char s_fcbattr;           /* 15: matched entry's attribute byte    */
            /* 16..1D: the matched entry's time/date/size, copied back out of the
             * directory entry by WRITE_DIR_ENTRY — the FCB time/pos overlay.       */
            unsigned int  s_time;              /* 16: matched entry's time              */
            unsigned int  s_date;              /* 18: its date                          */
            long          s_size;              /* 1A: its size                          */
            unsigned char s_name[8];           /* 1E: matched 8.3 filename stem (8 bytes)*/
            unsigned char s_ext[3];            /* 26: matched 8.3 file extension (3 bytes)*/
            unsigned char s_resv29[2];         /* 29: reserved padding (2 bytes)        */
        };                                     /* 2B: 43 bytes total                     */
        /* Near fragment descriptor passed to READ/WRITE_AT_FCB_POSITION: the leading
         * and trailing partial-fragment cluster/LBAs plus the caller's buffer segment. */
        struct frag_desc {
            union { long fr_cluster0;          /* 00: leading-fragment cluster        */
                    unsigned int fr_cluster0_lo; };  /* its low word (sector-align)   */
            union { long fr_cluster1;          /* 04: trailing-fragment cluster       */
                    unsigned int fr_cluster1_lo; };  /* its low word (sector-align)   */
            unsigned int  fr_seg;              /* 08: buffer segment                  */
        };
        /* DOS device-driver request packet (near, built on the stack).  Padded to the
         * 26-byte buffer BUILD_DRIVER_REQUEST reserves so the stack frame is unchanged. */
        struct request_packet {
            unsigned char r_len;               /* 00: packet length / opcode tag     */
            unsigned char r_unit;              /* 01: unit number                    */
            unsigned char r_cmd;               /* 02: command code                   */
            unsigned int  r_status;            /* 03: status word                    */
            unsigned char r_res[9];            /* 05: reserved + media descriptor    */
            unsigned long r_addr;              /* 0E: transfer address (far ptr)     */
            unsigned int  r_count;             /* 12: byte / sector count            */
            unsigned char r_res2[6];           /* 14: pad to 26 bytes                */
        };
        /* DOS_FN_44_IOCTL's on-stack driver packet: the request_packet header (len/
         * unit/cmd/status) whose payload is viewed as the DOS generic-IOCTL layout —
         * category @0D, function @0E, caller SI/DI images @0F/@11, and the far pointer
         * to the caller's parameter block @13.  Same 26-byte frame reservation as
         * struct request_packet (the media-check packet reuses i_cat for the media
         * descriptor byte at the same offset).                                       */
        struct ioctl_packet {
            unsigned char i_len;               /* 00: packet length                  */
            unsigned char i_unit;              /* 01: unit number                    */
            unsigned char i_cmd;               /* 02: command code                   */
            unsigned int  i_status;            /* 03: status word                    */
            unsigned char i_res[8];            /* 05: reserved                       */
            unsigned char i_cat;               /* 0D: category (8 = disk) / media    */
            unsigned char i_func;              /* 0E: function (CL)                  */
            unsigned int  i_si;                /* 0F: SI image (caller DS here)      */
            unsigned int  i_di;                /* 11: DI image (driver vec offset)   */
            unsigned char far *i_ptr;          /* 13: caller's parameter block DS:DX */
            unsigned char i_pad[3];            /* 17: pad to the 26-byte reservation */
        };
        /* The disk driver's internal request-building scratch at DS:0EE6h.  Fields are
         * populated per operation, then &REQ is dispatched (dispatch_request_packet /
         * disk_read_request / ...) which translates it into the on-stack DOS
         * request_packet.  Several 4-byte slots are reused polymorphically per request
         * type, hence the unions: the 0EE7 slot is a buffer pointer OR a raw sector
         * number; the 0EF4 slot is an LBA OR a DPB pointer; 0EF8 is the result OR a
         * second buffer pointer.  Each site uses the member matching how MSC declared
         * that access, so the codegen is byte-identical to the old scattered globals. */
        struct disk_request {
            unsigned char      q_op;           /* 00 0EE6: operation / drive          */
            union {                            /* 01 0EE7:                            */
                unsigned char far *q_buf;      /*     buffer pointer                  */
                long           q_sector;       /*     or raw sector number            */
            };
            unsigned int       q_pktseg;       /* 05 0EEB: packet segment             */
            unsigned int       q_valmid;       /* 07 0EED: value bits 8..23           */
            unsigned char      q_valtop;       /* 09 0EEF: value bits 24..31          */
            unsigned int       q_count;        /* 0A 0EF0: sector count               */
            unsigned char      q_x;            /* 0C 0EF2: sub-operation selector     */
            unsigned char      q_cmd;          /* 0D 0EF3: command (aka mode)         */
            union {                            /* 0E 0EF4:                            */
                long           q_lba;          /*     LBA                             */
                struct drive_param_block far *q_dpb; /* or the DPB pointer            */
            };
            union {                            /* 12 0EF8:                            */
                long           q_result;       /*     32-bit result                   */
                unsigned char far *q_buf2;     /*     or second buffer pointer        */
            };
        };                                     /* 16 bytes; 0EFC follows (not part)   */
        /* INT 21h caller register frame (the AH-dispatched service handlers receive a
         * far pointer to the saved registers; writing a field sets the value the caller
         * sees on return).  Byte accesses to a low half (AL @0, DL @6, ...) stay raw. */
        struct int21_regs {
            union { unsigned int r_ax; struct { unsigned char r_al; unsigned char r_ah; }; };  /* 00 */
            union { unsigned int r_bx; struct { unsigned char r_bl; unsigned char r_bh; }; };  /* 02 */
            union { unsigned int r_cx; struct { unsigned char r_cl; unsigned char r_ch; }; };  /* 04 */
            union { unsigned int r_dx; struct { unsigned char r_dl; unsigned char r_dh; }; };  /* 06 */
            unsigned int  r_si;                /* 08 */
            unsigned int  r_di;                /* 0A */
            unsigned int  r_bp;                /* 0C */
            unsigned int  r_ds;                /* 0E: caller's DS */
            unsigned int  r_es;                /* 10: caller's ES */
            unsigned int  r_ip;                /* 12: INT return frame */
            unsigned int  r_cs;                /* 14 */
            union { unsigned int r_flags; struct { unsigned char r_flagl; unsigned char r_flagh; }; };  /* 16 */
        };
