                if (xfer != 0) {
                    if (NETWORK_ACTIVE != 0) {
                        net_result = retry_network_loop(sft, xfer, 1);
                        if (net_result != 0) {
                            return lookup_error_msg(net_result);
                        }
                    }
                    DRIVER_VEC = sft->s_devptr;
                    if ((sft->s_flags & 4) == 0 && (sft->s_flags & 0x20) == 0) {
                        xfer = scan_for_ctrl_z(buffer, xfer);
