                        con_write_string(DRIVER_VEC, buffer, xfer);
                    }
                    *count = xfer;
                }
            }
            sft->s_offset += *count;
            if (NETWORK_ACTIVE != 0) {
                int2f_network_1086(sft, 1);
            }
            return 0;
        }
