            init_sda_driver_links();
            src = regs->r_bl;
            dst = regs->r_cl;
            if (find_sft_for_handle(src, &sft) == 0) {
                open_fcb_by_drive(dst);
                SDA_FILE_TABLE[dst] = SDA_FILE_TABLE[src];
                (sft->s_refcnt)++;
                result = 0;
            } else {
                result = lookup_error_msg(6);
            }
            set_int21_result(regs, result);
        }
        ;@endcompiled

DOS_FN_45_DUP_HANDLE:
        ; INT 21h AH=45h handler (dup handle)
        ;@compiled dos_fn_45_dup_handle 38BF 146
        /*
         * DOS_FN_45_DUP_HANDLE @ 0x38BF in SISNE.SIS (146 bytes).
         *
         * INT 21h AH=45h "Duplicate Handle" (dup): resolve the source FCB from its
         * handle (FCB+2); on failure raise error 6.  Otherwise find the first free slot
         * (0xFF) in the SDA file-handle table below the preserved size; if none, raise
         * error 4.  On success copy the source's SDA byte into the new slot, bump the
         * source record's reference count, store the new handle at FCB+0, and succeed.
         * Both error paths share the LOOKUP_ERROR_MSG tail (deferred past the body);
         * the success arm's structural jmp-over-else threads straight to the final
         * SET_INT21_RESULT call (dead-jmp elimination, #707).
         */

        void dos_fn_45_dup_handle(struct int21_regs far *regs) __addr__(0x38BF)
        {
            struct system_file_table far *sft; /* bp-4  */
            unsigned char result;              /* bp-6  */
            unsigned int src;                  /* bp-8  */
            unsigned int limit;                /* bp-0Ah */
            register unsigned int i;           /* SI */

            init_sda_driver_links();
            limit = get_sda_preserved_size();
            src = regs->r_bl;
            if (find_sft_for_handle(src, &sft) == 0) {
                for (i = 0; limit > i; i++) {
                    if (SDA_FILE_TABLE[i] == 0xFF) {
                        break;
                    }
                }
                if (limit > i) {
                    SDA_FILE_TABLE[i] = SDA_FILE_TABLE[src];
                    (sft->s_refcnt)++;
                    regs->r_ax = i;
                    result = 0;
                } else {
                    result = lookup_error_msg(4);
                }
            } else {
                result = lookup_error_msg(6);
            }
            set_int21_result(regs, result);
        }
        ;@endcompiled

DOS_FN_44_IOCTL:
        ; INT 21h AH=44h handler (ioctl)
        ;@compiled dos_fn_44_ioctl 3951 1317
        /*
         * DOS_FN_44_IOCTL @ 0x3951 in SISNE.SIS (1317 bytes).
         *
         * INT 21h AH=44h handler (IOCTL) — the biggest single function in the image,
         * and the one real MSC dense-table `switch` (16-entry `cs:` jump table at the
         * end of the case bodies; value 0Ch and >0Fh are rejected up front, so their
         * slots point at the after-switch confluence).
         *
         * Three setup phases before the dispatch: handle-based subfunctions (0-3, 6,
         * 7, 0Ah) resolve the FCB record and its device / DPB driver vector;
         * drive-based ones (4, 5, 8, 9, 0Dh-0Fh) map BL through GET_DRIVE_TYPE to a
         * CDS entry and its DPB.  Subfunctions 2-5 and 0Dh capture the caller's DS:DX
         * parameter pointer.  Any recorded error skips the switch entirely.
         *
         * The shared `raise:` invalid-function block sits in case 0Dh's validation
         * arm (the fall-into copy) with the other cases jumping to it, and the driver
         * status funnel (`drv_err`) in case 0Dh serves case 0Eh/0Fh too — the ROM's
         * cross-case E9s/JCCs are the image of goto source.  case 8's device-check
         * arm gotos into its own status arm (`media_err`).  The remaining sharing
         * (the unit-arg call tail of cases 4/5 into 2/3, case 9's masked-attr store
         * into case 0Ah) is MSC's cross-jumping, which tiny_cc now models.
         */

        extern struct device_header far *DRIVER_VEC __addr__(0x0F0A);

        void dos_fn_44_ioctl(struct int21_regs far *regs) __addr__(0x3951)
        {
            unsigned char cmd;                 /* bp-2   */
            struct system_file_table far *sft; /* bp-6   */
            unsigned char is_dev;              /* bp-8   */
            unsigned int handle;               /* bp-0Ah */
            struct ioctl_packet pkt;           /* bp-24h */
            unsigned int result;               /* bp-26h */
            unsigned int cflags;               /* bp-28h */
            unsigned char far *dsdx;           /* bp-2Ch: caller DS:DX */
            struct drive_param_block far *dpb; /* bp-30h */
            unsigned int count;                /* bp-32h */
            unsigned char attr;                /* bp-34h */
            unsigned char err;                 /* bp-36h */
            unsigned char op;                  /* bp-38h */
            struct cds_entry far *entry;       /* bp-3Ch */

            op = regs->r_al;
            err = 0;
            if (op > 0x0F || op == 0x0C) {
                err = (unsigned char)lookup_error_msg(1, 1);
            } else if (op <= 3 || op == 6 || op == 7 || op == 0x0A) {
                handle = regs->r_bx;
                if (find_sft_for_handle(handle, &sft) != 0) {
                    err = (unsigned char)lookup_error_msg(6);
                } else {
                    is_dev = sft->s_flags & 0x80;
                    if (is_dev != 0) {
                        DRIVER_VEC = sft->s_devptr;
                    } else {
                        dpb = sft->s_devptr;
                        FCB_DRIVE = dpb->d_drive;
                        DRIVER_VEC = dpb->d_driver;
                    }
                }
            } else if (op != 0x0B) {
                is_dev = 0;
                FCB_DRIVE = (unsigned char)get_drive_type(regs->r_bl);
                if (FCB_DRIVE == 0xFF) {
                    err = (unsigned char)lookup_error_msg(0x0F);
                } else {
                    entry = &DPB_TABLE[FCB_DRIVE];
                    FCB_DRIVE = entry->c_drvletter - 'A';
                    if (op != 9 && (entry->c_dpbo | entry->c_dpbs) == 0) {
                        err = (unsigned char)lookup_error_msg(1, 1);
                    } else {
                        dpb = get_dpb_by_drive_index(FCB_DRIVE);
                        DRIVER_VEC = dpb->d_driver;
                    }
                }
            }
            if ((op >= 2 && op <= 5) || op == 0x0D) {
                FP_SEG(dsdx) = regs->r_ds;
                FP_OFF(dsdx) = regs->r_dx;
            }
            if (err == 0) {
                switch (op) {
                case 0:
                    regs->r_dx = DRIVER_VEC->dh_attr;
                    if (is_dev == 0) {
                        regs->r_dh = 0;
                    }
                    regs->r_dl = sft->s_flags;
                    regs->r_ax = regs->r_dx;
                    break;
                case 1:
                    if (is_dev == 0) {
                        goto raise;
                    }
                    sft->s_flags = regs->r_dl;
                    break;
                case 2:
                case 3:
                    if (is_dev == 0) {
                        goto raise;
                    }
                    if ((DRIVER_VEC->dh_attr & 0x4000) == 0) {
                        goto raise;
                    }
                    if (op == 2) {
                        cmd = 3;
                    } else {
                        cmd = 0x0C;
                    }
                    result = build_driver_request(cmd, 0, regs, DRIVER_VEC, (unsigned long)dsdx);
                    break;
                case 4:
                case 5:
                    if (is_dev != 0 || (DRIVER_VEC->dh_attr & 0x4000) == 0) {
                        err = (unsigned char)lookup_error_msg(1, 1);
                    }
                    if (op == 4) {
                        cmd = 3;
                    } else {
                        cmd = 0x0C;
                    }
                    result = build_driver_request(cmd, dpb->d_unit, regs, DRIVER_VEC,
                                                  (unsigned long)dsdx);
                    break;
                case 6:
                case 7:
                    if (is_dev != 0) {
                        if (op == 6) {
                            cmd = 6;
                        } else {
                            cmd = 0x0A;
                        }
                        result = build_driver_request(cmd, 0, regs, DRIVER_VEC, attr);
                        if ((result & 0x200) == 0) {
                            regs->r_al = 0xFF;
                        } else {
                            regs->r_al = 0;
                        }
                    } else if ((sft->s_model & 1) != 0) {
                        regs->r_ah = 1;
                        regs->r_al = 0xFF;
                    } else {
                        count = 1;
                        result = (unsigned char)fcb_random_block_io(handle, &attr, &count);
                        if (count == 0) {
                            regs->r_ax = 0x1A00;
                        } else {
                            sft->s_offset -= 1;
                            regs->r_ah = attr;
                            regs->r_al = 0xFF;
                        }
                    }
                    break;
                case 8:
                    if ((entry->c_flags & 0x8000) != 0) {
                        goto raise;
                    }
                    if ((DRIVER_VEC->dh_attr & 0x800) == 0) {
                        goto media_err;
                    }
                    pkt.i_len = 0x0D;
                    pkt.i_unit = dpb->d_unit;
                    pkt.i_cmd = 0x0F;
                    pkt.i_status = 0;
                    pkt.i_cat = dpb->d_media;
                    call_driver_with_packet(&pkt, DRIVER_VEC);
                    if ((pkt.i_status & 0x200) != 0) {
                    media_err:
                        regs->r_ax = 1;
                    } else {
                        regs->r_ax = 0;
                    }
                    break;
                case 9:
                    cflags = entry->c_flags;
                    if ((cflags & 0x8000) != 0) {
                        regs->r_dx = 0x1000;
                    } else {
                        regs->r_dx = DRIVER_VEC->dh_attr & 0xEFFF;
                    }
                    break;
                case 0x0A:
                    cflags = DPB_TABLE[FCB_DRIVE].c_flags;
                    if ((cflags & 0x8000) != 0) {
                        regs->r_dx = cflags;
                    } else {
                        regs->r_dh = sft->s_res;
                        regs->r_dl = sft->s_flags;
                    }
                    break;
                case 0x0B:
                    RETRY_LIMIT = regs->r_dx + 1;
                    RETRY_PAUSE = regs->r_cx;
                    break;
                case 0x0D:
                    cmd = regs->r_cl & 0xDF;
                    if ((entry->c_flags & 0x8000) != 0 || (DRIVER_VEC->dh_attr & 0x40) == 0 ||
                        regs->r_ch != 8 || cmd < 0x40 || cmd > 0x42) {
                    raise:
                        err = (unsigned char)lookup_error_msg(1, 1);
                    } else {
                        pkt.i_len = 0x17;
                        pkt.i_unit = dpb->d_unit;
                        pkt.i_cmd = 0x13;
                        pkt.i_status = 0;
                        pkt.i_cat = 8;
                        pkt.i_func = regs->r_cl;
                        pkt.i_si = regs->r_ds;
                        pkt.i_di = FP_OFF(DRIVER_VEC);
                        FP_OFF(pkt.i_ptr) = regs->r_dx;
                        FP_SEG(pkt.i_ptr) = regs->r_ds;
                        call_driver_with_packet(&pkt, DRIVER_VEC);
                        if ((pkt.i_status & 0x8000) != 0) {
                        drv_err:
                            err = (unsigned char)lookup_default_error(pkt.i_status, 2);
                        }
                    }
                    break;
                case 0x0E:
                case 0x0F:
                    if ((DRIVER_VEC->dh_attr & 0x40) == 0) {
                        goto raise;
                    }
                    pkt.i_len = 0x0D;
                    pkt.i_unit = dpb->d_unit + 1;
                    if (op == 0x0E) {
                        pkt.i_cmd = 0x17;
                    } else {
                        pkt.i_cmd = 0x18;
                    }
                    pkt.i_status = 0;
                    call_driver_with_packet(&pkt, DRIVER_VEC);
                    if ((pkt.i_status & 0x8000) != 0) {
                        goto drv_err;
                    }
                    regs->r_al = pkt.i_unit;
                    break;
                }
            }
            set_int21_result(regs, err);
        }
        ;@endcompiled

DOS_FN_68_RESERVED_68:
        ; INT 21h AH=68h handler (reserved 68)
        ;@compiled dos_fn_68_reserved_68 3E76 93
        /*
         * DOS_FN_68_RESERVED_68 @ 0x3E76 in SISNE.SIS (93 bytes).
         *
         * INT 21h AH=68h "Commit File" (fflush): resolve the FCB from its handle
         * (FCB+2); on failure report error 6.  Otherwise stamp the current DOS
         * date/time into the record (sft+0x0D time, sft+0x0F date) and flush it through
         * DISPATCH_FCB_OPEN, reporting that status.  Both outcomes are handed to
         * SET_INT21_RESULT (the two calls share their tail).
         */

        void dos_fn_68_reserved_68(struct int21_regs far *regs) __addr__(0x3E76)
        {
            struct system_file_table far *sft; /* bp-4  */
            unsigned int fdate;                /* bp-6  */
            unsigned int handle;               /* bp-8  */
            unsigned int ftime;                /* bp-0Ah */

            handle = regs->r_bx;
            if (find_sft_for_handle(handle, &sft) != 0) {
                set_int21_result(regs, 6);
            } else {
                build_dos_datetime(&fdate, &ftime);
                sft->s_date = fdate;
                sft->s_time = ftime;
                set_int21_result(regs, (unsigned char)dispatch_fcb_open(sft));
            }
        }
        ;@endcompiled

SAVE_DOS_RETURN_FRAME:
        ; Save AX/DX into the DOS return-state pair at SDA_DTA/[02DCh]
        ;@compiled save_dos_return_frame 3ED3 18
        /*
         * SAVE_DOS_RETURN_FRAME @ 0x3ED3 in SISNE.SIS (18 bytes).
         *
         * Store the DTA far pointer (offset in AX, segment in DX, as one 32-bit value)
         * into SDA_DTA at ds:[2DAh]/[2DCh] — a long view of the same far pointer the
         * DTA getters/setters access word-wise.
         */

        void save_dos_return_frame(unsigned char far *v) __addr__(0x3ED3) { SDA_DTA = v; }
        ;@endcompiled

SET_FCB_FILE_POSITION:
        ; FIND_SFT_FOR_HANDLE then issue shrink/truncate via the dispatch tail
        ;@compiled set_fcb_file_position 3EE5 44
        /*
         * SET_FCB_FILE_POSITION @ 0x3EE5 in SISNE.SIS (44 bytes).
         *
         * Look up the SDA file record for `drive` (FIND_SFT_FOR_HANDLE) and, when found,
         * overwrite its 32-bit size/position field at record+0x15 with `value`.
         */

        void set_fcb_file_position(int drive, long value) __addr__(0x3EE5)
        {
            struct system_file_table far *sft; /* bp-4 */

            if (find_sft_for_handle(drive, &sft) != 0) {
                return;
            }
            sft->s_offset = value;
        }
        ;@endcompiled

INSTALL_FIRST_DRIVER:
        ; Init [1424h/1422h/1430h/142Eh] tables; walk FCB chain for first driver
        ;@compiled install_first_driver 3F11 190
        /*
         * INSTALL_FIRST_DRIVER @ 0x3F11 in SISNE.SIS (190 bytes).
         *
         * Re-anchor the swappable-data-area pointers at the caller's PSP and then walk
         * the process's file-handle table, bumping the reference count of every SFT
         * record a live handle points at.
         */

        void install_first_driver(void) __addr__(0x3F11)
        {
            struct system_file_table far *entry; /* bp-4 / bp-2 */
            unsigned int rem;                    /* bp-6 */
            unsigned int i;                      /* bp-8 */
            unsigned int limit;                  /* bp-0x0a */
            unsigned int handle;                 /* bp-0x0c */
            struct file_block far *chain;        /* bp-0x10 / bp-0x0e */

            SDA_SEG = SDA_SRC_SEG;
            FP_OFF(SDA_PTR) = 0;
            FP_SEG(SDA_FILE_TABLE) = SDA_SRC_SEG;
            FP_OFF(SDA_FILE_TABLE) = 0x18;
            limit = get_sda_preserved_size();
            for (i = 0; i < limit; i++) {
                handle = SDA_FILE_TABLE[i];
                if (handle == 0xFF) {
                    continue;
                }
                chain = DRIVER_CHAIN_HEAD;
                rem = handle;
                while (FP_OFF(chain) != 0xFFFF) {
                    if (chain->b_count <= rem) {
                        rem -= chain->b_count;
                        chain = chain->b_next;
                    } else {
                        entry = &chain->b_rec[rem];
                        if ((entry->s_res & 0x10) != 0) {
                            SDA_FILE_TABLE[i] = 0xFF;
                        } else {
                            entry->s_refcnt++;
                        }
                        break;
                    }
                }
            }
        }
        ;@endcompiled

CLOSE_PSP_FILES:
        ; Process exit (from INT22_EXIT_DISPATCH) — close every file the PSP owns
        ;@compiled close_psp_files 3FCF 357
        /*
         * CLOSE_PSP_FILES @ 0x3FCF in SISNE.SIS (357 bytes).
         *
         * RENAMED from INSTALL_DRIVER, which was a misnomer of the same family as
         * RENAME_FILE_BY_FCB (see the note near .rev line 2520): nothing installs a driver.  This
         * is the process-exit path — close every file the PSP owns.  First, with a redirector
         * present, sweep the SFT table for records owned by this PSP, zero-filling device records
         * and closing the rest.  Then walk the PSP's job file table: for each live handle, follow
         * the SFT block chain to its record, stamp the current date/time, flush it through
         * DISPATCH_FCB_OPEN, drop the reference count, notify SHARE, and mark the JFT slot free.
         */

        extern void call_resident_install(unsigned int handle) __addr__(0xC97A);

        void close_psp_files(unsigned int psp) __addr__(0x3FCF)
        {
            struct system_file_table far *sft; /* bp-4 / bp-2  */
            unsigned int date;                 /* bp-6         */
            unsigned int limit;                /* bp-8         */
            unsigned int idx;                  /* bp-0Ah       */
            register unsigned int si;          /* SI, home bp-0Ch */
            unsigned int handle;               /* bp-0Eh       */
            unsigned int time;                 /* bp-10h       */
            struct file_block far *blk;        /* bp-14h / bp-12h */

            SDA_SEG = psp;
            FP_OFF(SDA_PTR) = 0;
            if (NETWORK_ACTIVE != 0) {
                si = 0;
                while (si < DRIVER_COUNT) {
                    sft = &DRIVER_TABLE->b_rec[si];
                    if (sft->s_refcnt != 0 && sft->s_ownpsp == psp) {
                        if ((sft->s_res & 0x80) != 0) {
                            mem_fill_zero((unsigned char far *)sft, 0x35);
                        } else {
                            sft->s_refcnt = 1;
                            close_sft_entry(sft);
                        }
                    }
                    si++;
                }
            }
            FP_SEG(SDA_FILE_TABLE) = SDA_PTR->p_filetabseg;
            FP_OFF(SDA_FILE_TABLE) = SDA_PTR->p_filetaboff;
            limit = get_sda_preserved_size();
            for (si = 0; si < limit; si++) {
                handle = SDA_FILE_TABLE[si];
                if (handle == 0xFF) {
                    continue;
                }
                blk = DRIVER_CHAIN_HEAD;
                idx = handle;
                for (;;) {
                    if (FP_OFF(blk) == 0xFFFF) {
                        goto next_handle;
                    }
                    if (blk->b_count > idx) {
                        break;
                    }
                    idx -= blk->b_count;
                    blk = blk->b_next;
                }
                sft = &blk->b_rec[idx];
                if ((sft->s_res & 0x80) != 0) {
                    call_resident_install(si);
                } else {
                    build_dos_datetime(&date, &time);
                    sft->s_date = date;
                    sft->s_time = time;
                    dispatch_fcb_open(sft);
                    if (sft->s_refcnt > 0) {
                        sft->s_refcnt--;
                    }
                    if (NETWORK_ACTIVE != 0) {
                        notify_share_fcb(sft);
                    }
                }
                SDA_FILE_TABLE[si] = 0xFF;
            next_handle:;
            }
        }
        ;@endcompiled
        ;@compiled write_fcb_to_con_or_driver 4134 70
        /*
         * WRITE_FCB_TO_CON_OR_DRIVER @ 0x4134 in SISNE.SIS (70 bytes).
         *
         * If the FCB record is flagged for the console (sft->s_flags bit 7) and its driver
         * has the CON attribute (driver+4 bit 0x800), build a 1-byte device packet
         * (command 0x0D, the op byte at +2) and dispatch it to the driver.
         */

        extern struct device_header far *DRIVER_VEC __addr__(0x0F0A);

        void write_fcb_to_con_or_driver(int op, struct system_file_table far *sft)
            __addr__(0x4134)
        {
            unsigned char buf[30]; /* bp-1E */

            if ((sft->s_flags & 0x80) == 0) {
                return;
            }
            DRIVER_VEC = sft->s_devptr;
            if ((DRIVER_VEC->dh_attr & 0x800) == 0) {
                return;
            }
            buf[0] = 0x0D;
            buf[2] = op;
            /* The two halves, NOT `DRIVER_VEC` whole: here the ROM pushes the words
             * still live in DX:BX from the store and `les` above (`push dx; push bx`),
             * which is what the split spelling emits.  Handing the pointer over as one
             * argument re-reads it from memory and costs 6 bytes. */
            call_driver_with_packet(buf, FP_OFF(DRIVER_VEC), FP_SEG(DRIVER_VEC));
        }
        ;@endcompiled

INSTALL_INT_HANDLERS:
        ; Patch IVT — install SISNE's INT 0/1/3/4, 20..3F, and 0x21, 0x25 handlers
        push    ds                                             ;#417A: 1E
        mov     ax, 0                                          ;#417B: B8 00 00
        mov     ds, ax                                         ;#417E: 8E D8
        mov     word [0], DIVIDE_ERROR_HANDLER                 ;#4180: C7 06 00 00 C8 42
        mov     word [2], 70h                                  ;#4186: C7 06 02 00 70 00
        mov     cx, 20h                                        ;#418C: B9 20 00
        mov     bx, 80h                                        ;#418F: BB 80 00
