        ; Loop body — write (NULL_INT_HANDLER, cs) into IVT[20..3F] entries
        mov     word [bx], NULL_INT_HANDLER                    ;#4192: C7 07 CB 44
        inc     bx                                             ;#4196: 43
        inc     bx                                             ;#4197: 43
        mov     [bx], cs                                       ;#4198: 8C 0F
        inc     bx                                             ;#419A: 43
        inc     bx                                             ;#419B: 43
        loop    INSTALL_INT_NULL_LOOP                          ;#419C: E2 F4
