            unsigned char flag_del;        /* bp-8 */
            unsigned char attr;            /* bp-0xa */
            register int si;               /* SI (home bp-0xc) */
            unsigned char flag_e;          /* bp-0xe */
            unsigned char far *work;       /* bp-0x12 / bp-0x10 */
