            unsigned int pad_16;           /* bp-0x16 */
            unsigned char attr;            /* bp-0x18 */
            unsigned int pad_1a;           /* bp-0x1a */
            unsigned char flag_dev;        /* bp-0x1c */
            unsigned char far *work;       /* bp-0x1e / bp-0x20 */
