            network_or_local_copy(dir_ent, dpb);
            mem_copy_far(SRCH_FCB.f_name, WORK_FCB.f_name, 0x0B);
            if (0xC7 - qcount == idx) {
                lookup_error_msg(0x57);
                rec->r_al = 0xFF;
                return;
