        mov     bp, sp                                         ;#B904: 8B EC
        mov     al, [CURRENT_DRIVE]                            ;#B906: A0 E4 02
        les     di, [bp+2]                                     ;#B909: C4 7E 02
        mov     [es:di], al                                    ;#B90C: 26 88 05
        ret                                                    ;#B90F: C3

