KBD_XLATE_TBL_SCAN_LOOP:
        ; lodsb in keyboard-scancode translation 14-entry table scan
        lodsb                                                  ;#DC84: AC
        int     29h                                            ;#DC85: CD 29
        loop    KBD_XLATE_TBL_SCAN_LOOP                        ;#DC87: E2 FB
KBD_XLATE_TBL_RESTORE_DS:
        ; pop ds tail after KBD translation table scan
        pop     ds                                             ;#DC89: 1F
        mov     ax, 100h                                       ;#DC8A: B8 00 01
        ret                                                    ;#DC8D: C3

XLATE_KBD_SCANCODE:
        ; Match BIOS INT 16h ext scan codes (7200h..5D84h) and emit control byte in AL
        push    bx                                             ;#DC8E: 53
        push    ds                                             ;#DC8F: 1E
        mov     bx, 0FA1h                                      ;#DC90: BB A1 0F
        mov     ds, bx                                         ;#DC93: 8E DB
        cmp     byte [BRASCII_MODE], 2                         ;#DC95: 80 3E 34 03 02
        jnz     short KBD_TRANSLATE_RET                        ;#DC9A: 75 25
        mov     bl, 10h                                        ;#DC9C: B3 10
        cmp     ax, 7200h                                      ;#DC9E: 3D 00 72
        jz      short XLATE_KBD_AL_FROM_BL                     ;#DCA1: 74 1C
        mov     bl, 0Ah                                        ;#DCA3: B3 0A
        cmp     ax, 6305h                                      ;#DCA5: 3D 05 63
        jz      short XLATE_KBD_AL_FROM_BL                     ;#DCA8: 74 15
        mov     bl, 8Ch                                        ;#DCAA: B3 8C
        cmp     ax, 5C82h                                      ;#DCAC: 3D 82 5C
        jz      short XLATE_KBD_AL_FROM_BL                     ;#DCAF: 74 0E
        mov     bl, 8Ah                                        ;#DCB1: B3 8A
        cmp     ax, 5B83h                                      ;#DCB3: 3D 83 5B
        jz      short XLATE_KBD_AL_FROM_BL                     ;#DCB6: 74 07
        mov     bl, 8Bh                                        ;#DCB8: B3 8B
        cmp     ax, 5D84h                                      ;#DCBA: 3D 84 5D
        jnz     short KBD_TRANSLATE_RET                        ;#DCBD: 75 02
XLATE_KBD_AL_FROM_BL:
        ; Final branch — AL = BL (translated control byte); pop ds/bx
        mov     al, bl                                         ;#DCBF: 8A C3
KBD_TRANSLATE_RET:
        ; Common pop ds/bx ret tail of keyboard scancode → control-byte translator
        pop     ds                                             ;#DCC1: 1F
        pop     bx                                             ;#DCC2: 5B
        ret                                                    ;#DCC3: C3

